class CircleData {
  constructor(public readonly radius: number) {}
}

class Circle {
  private readonly data: CircleData; // sealed at construction, never reassigned

  constructor(radius: number) {
    this.data = new CircleData(radius);
  }

  area(): number {
    return Math.PI * this.data.radius ** 2; // always the original, correct radius
  }

  // 'Scaling' now returns a NEW Circle instead of mutating this one
  scaled(factor: number): Circle {
    return new Circle(this.data.radius * factor);
  }
}
